      const shares = pmBuyOrderShares(apiBetMoney, limitPrice, orderOptions.tickSize);
      if (!Number.isFinite(shares) || shares < orderOptions.minOrderSize)
        throw new Error("Polymarket 下单金额低于最小份数（实际签单限价）");
