        tokenId,
        accountId: Number(account.accountId) || undefined,
        ms: performance.now() - checkStartedAt,
        success: false,
        error: option.checkError,
        detectionOdds,
        detectionMaxPrice: maxPrice,
        apiBetMoney,
      });
    }
    return option;
  },

